'use strict';
const express=require('express'),crypto=require('crypto'),fs=require('fs'),path=require('path');
const{db}=require('../db'),{DATA_DIR}=require('../paths'),{dispatcher}=require('../dispatcher'),{broadcast}=require('../ws'),{validateGraph,compileNode}=require('../spaceSpec');
const {listRefs,publishRefs:publishPublicRefs}=require('../referenceLibrary');
const router=express.Router();
db.exec(`CREATE TABLE IF NOT EXISTS monday_spaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,graph TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS monday_space_runs(id TEXT PRIMARY KEY,space_id TEXT NOT NULL,status TEXT NOT NULL,graph TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);`);
try{db.exec('ALTER TABLE monday_spaces ADD COLUMN archived_at TEXT')}catch{}
db.pragma('busy_timeout = 3000');
const busyError=e=>/locked|busy/i.test(e.message||'');
const now=()=>new Date().toISOString(),id=()=>crypto.randomUUID(),parse=r=>r?{...r,graph:JSON.parse(r.graph),...(r.state?{state:JSON.parse(r.state)}:{})}:null;
router.use((req,res,next)=>{const origin=req.get('origin'),allowed=['http://localhost:3001','http://127.0.0.1:3001'];if(process.env.MUSE_STAGING_PORT)allowed.push('http://localhost:'+process.env.MUSE_STAGING_PORT);if(!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress)||(origin&&!allowed.includes(origin)))return res.status(403).json({error:'Chỉ sử dụng trên máy này'});next()});
router.use('/production',require('../videoProduction').router);
router.use('/components',require('../spaceComponents').router);
router.use('/media',require('../spaceMedia').router);
router.get('/',(req,res)=>res.json(db.prepare('SELECT id,name,version,updated_at,archived_at FROM monday_spaces WHERE archived_at IS '+(req.query.archived==='1'?'NOT NULL':'NULL')+' ORDER BY updated_at DESC').all()));
router.delete('/:id',(req,res)=>{if(db.prepare("SELECT id FROM monday_space_runs WHERE space_id=? AND status='running'").get(req.params.id))return res.status(409).json({error:'Dừng hoặc chờ tác vụ hoàn tất trước khi đưa Space vào thùng rác'});const r=db.prepare('UPDATE monday_spaces SET archived_at=? WHERE id=?').run(now(),req.params.id);res.json({success:!!r.changes})});
router.post('/:id/restore',(req,res)=>{db.prepare('UPDATE monday_spaces SET archived_at=NULL WHERE id=?').run(req.params.id);res.json({success:true})});
router.post('/maintenance/cache',(req,res)=>{if(db.prepare("SELECT id FROM monday_space_runs WHERE status='running' LIMIT 1").get())return res.status(409).json({error:'Chờ workflow hoàn tất trước khi dọn bộ nhớ đệm'});const count=displayGraphs.size;displayGraphs.clear();res.json({success:true,count,note:'Đã dọn bộ nhớ đệm xử lý. Ảnh, video, mô tả và lịch sử được giữ nguyên.'})});
router.post('/',(req,res)=>{const errors=validateGraph(req.body?.graph);if(errors.length)return res.status(400).json({error:errors.join('\n'),errors});const spaceId=id();db.prepare('INSERT INTO monday_spaces(id,name,graph,updated_at) VALUES(?,?,?,?)').run(spaceId,String(req.body?.name||'Space mới').slice(0,120),JSON.stringify(req.body?.graph),now());res.status(201).json(parse(db.prepare('SELECT * FROM monday_spaces WHERE id=?').get(spaceId)))});
router.get('/runs/:id',(req,res)=>{const run=parse(db.prepare('SELECT * FROM monday_space_runs WHERE id=?').get(req.params.id));if(!run)return res.status(404).json({error:'Không tìm thấy lượt chạy'});const jobs={};for(const state of Object.values(run.state))if(state.jobId){const j=db.prepare('SELECT id,status,progress,error,video_url,media_type,archived_at FROM jobs WHERE id=?').get(state.jobId);if(j)jobs[state.jobId]=j}res.json({...run,jobs})});
router.post('/runs/:id/cancel',(req,res)=>{const run=parse(db.prepare('SELECT * FROM monday_space_runs WHERE id=?').get(req.params.id));if(!run)return res.status(404).json({error:'Không tìm thấy lượt chạy'});if(run.status!=='running')return res.status(409).json({error:'Lượt chạy đã kết thúc'});for(const n of run.graph.nodes)if(['motion','combine','aiPrompt','upscale','download','splitStoryboard','pickImage'].includes(n.data.kind)){const key=run.id+':'+n.id+':'+(run.state[n.id]?.retry||0);require('../spaceMedia').cancel(key);require('../spaceComponents').cancel(key)}const running=[];db.transaction(()=>{for(const s of Object.values(run.state)){if(s.jobId){const job=db.prepare('SELECT status FROM jobs WHERE id=?').get(s.jobId);if(job?.status==='running')running.push(s.jobId);if(job?.status==='pending')db.prepare("UPDATE jobs SET status='stopped' WHERE id=?").run(s.jobId)}if(!['completed','failed','blocked'].includes(s.status))s.status='cancelled'}db.prepare("UPDATE monday_space_runs SET status='cancelled',state=?,updated_at=? WHERE id=?").run(JSON.stringify(run.state),now(),run.id)})();for(const jobId of running)dispatcher.stopJob(jobId);res.json({success:true})});
router.post('/runs/:id/retry',(req,res)=>{const run=parse(db.prepare('SELECT * FROM monday_space_runs WHERE id=?').get(req.params.id));if(!run)return res.status(404).json({error:'Không tìm thấy lượt chạy'});if(!['failed','cancelled'].includes(run.status))return res.status(409).json({error:'Chỉ thử lại lượt lỗi hoặc đã dừng'});if(db.prepare("SELECT id FROM monday_space_runs WHERE space_id=? AND status='running'").get(run.space_id))return res.status(409).json({error:'Space đang có lượt chạy khác'});for(const [key,s]of Object.entries(run.state))if(!['completed','idle'].includes(s.status))run.state[key]={status:'waiting',retry:(s.retry||0)+1};db.prepare("UPDATE monday_space_runs SET status='running',state=?,updated_at=? WHERE id=?").run(JSON.stringify(run.state),now(),run.id);res.json({id:run.id,status:'running'});tick()});
router.post('/runs/:id/nodes/:node/approve',(req,res)=>{const run=parse(db.prepare('SELECT * FROM monday_space_runs WHERE id=?').get(req.params.id));if(!run||run.status!=='running'||run.state[req.params.node]?.status!=='review')return res.status(409).json({error:'Bước này không ở trạng thái chờ duyệt'});run.state[req.params.node].status='completed';db.prepare('UPDATE monday_space_runs SET state=?,updated_at=? WHERE id=?').run(JSON.stringify(run.state),now(),run.id);res.json({success:true});tick()});
router.post('/runs/:id/nodes/:node/retry',(req,res)=>{const run=parse(db.prepare('SELECT * FROM monday_space_runs WHERE id=?').get(req.params.id));if(!run||run.status!=='running'||run.state[req.params.node]?.status!=='review')return res.status(409).json({error:'Chỉ tạo lại ảnh đang chờ duyệt'});const previous=run.state[req.params.node];run.state[req.params.node]={status:'waiting',retry:(previous.retry||0)+1};db.prepare('UPDATE monday_space_runs SET state=?,updated_at=? WHERE id=?').run(JSON.stringify(run.state),now(),run.id);res.json({success:true});tick()});
const displayGraphs=new Map();function displayGraph(g){const key=crypto.createHash('sha256').update(JSON.stringify({nodes:g.nodes.map(n=>({id:n.id,data:{...n.data,label:undefined,color:undefined}})),edges:g.edges.filter(e=>e.data?.enabled!==false).map(e=>({source:e.source,target:e.target,targetHandle:e.targetHandle,role:e.data?.role}))})).digest('hex');if(!displayGraphs.has(key)){if(displayGraphs.size>=64)displayGraphs.delete(displayGraphs.keys().next().value);displayGraphs.set(key,g)}return displayGraphs.get(key)}
router.get('/:id/activity',(req,res)=>{const space=parse(db.prepare('SELECT * FROM monday_spaces WHERE id=?').get(req.params.id));if(!space||space.archived_at)return res.status(404).json({error:'Space không tồn tại hoặc đang trong thùng rác'});const runs=db.prepare("SELECT * FROM monday_space_runs WHERE space_id=? AND status='running' ORDER BY created_at").all(req.params.id).map(parse).map(run=>{const jobs={};for(const state of Object.values(run.state))if(state.jobId){const j=db.prepare('SELECT id,status,progress,error,video_url,media_type,archived_at FROM jobs WHERE id=?').get(state.jobId);if(j)jobs[state.jobId]=j}return {...run,jobs}}),outputs={},current=displayGraph(space.graph);for(const r of db.prepare('SELECT * FROM monday_space_runs WHERE space_id=? ORDER BY updated_at DESC,created_at DESC LIMIT 30').all(req.params.id).map(parse)){const source=displayGraph(r.graph.editorGraph||r.graph);for(const [id,state]of Object.entries(r.state)){if(outputs[id]||state.status!=='completed'||!require('../spaceSmart').validSnapshot(state.output))continue;try{if(fingerprint(source,id)===fingerprint(current,id))outputs[id]=state}catch{}}}res.json({runs,outputs})});

router.get('/:id',(req,res)=>{const space=parse(db.prepare('SELECT * FROM monday_spaces WHERE id=?').get(req.params.id));if(!space||space.archived_at)return res.status(404).json({error:'Space không tồn tại hoặc đang trong thùng rác'});res.json({...space,runs:db.prepare('SELECT id,status,created_at FROM monday_space_runs WHERE space_id=? ORDER BY created_at DESC LIMIT 20').all(req.params.id)})});
router.put('/:id',(req,res)=>{const errors=validateGraph(req.body?.graph);if(errors.length)return res.status(400).json({error:errors.join('\n'),errors});const result=db.prepare('UPDATE monday_spaces SET name=?,graph=?,version=version+1,updated_at=? WHERE id=? AND version=?').run(String(req.body?.name||'Space mới').slice(0,120),JSON.stringify(req.body?.graph),now(),req.params.id,Number(req.body?.version));if(!result.changes)return res.status(409).json({error:'Space đã thay đổi ở nơi khác. Tải lại trước khi lưu để tránh ghi đè.'});res.json(parse(db.prepare('SELECT * FROM monday_spaces WHERE id=?').get(req.params.id)))});
router.post('/:id/run',(req,res)=>{const space=parse(db.prepare('SELECT * FROM monday_spaces WHERE id=?').get(req.params.id));if(!space||space.archived_at)return res.status(404).json({error:'Space không tồn tại hoặc đang trong thùng rác'});if(space.graph.nodes.some(n=>['cutout','upscale'].includes(n.data.kind)))return res.status(400).json({error:'Tách nền và upscale đã được gỡ. Xóa node cũ trước khi chạy.'});const errors=validateGraph(space.graph,{ready:true,cachedIds:space.graph.nodes.filter(n=>require('../spaceSmart').validSnapshot(n.data.savedOutput)).map(n=>n.id)});if(space.graph.nodes.some(n=>n.data.kind==='aiPrompt')&&!require('../spaceComponents').aiConfigured())errors.push('Node viết prompt cần tài khoản MUSE trong Cài đặt');if(space.graph.nodes.some(n=>n.data.kind==='motion')&&!require('../spaceMedia').configured())errors.push('Motion Control chưa kết nối fal.ai. Mở node và nhập API key trước khi chạy.');for(const n of space.graph.nodes)if(n.data.kind==='source'&&!require('../spaceSmart').validSnapshot(n.data.savedOutput)){const ref=db.prepare('SELECT filepath,archived_at FROM ref_images WHERE tag=?').get(n.data.refTag||'');if(!ref||ref.archived_at||!fs.existsSync(ref.filepath))errors.push('Ảnh nguồn không còn: @'+(n.data.refTag||'?'))}if(errors.length)return res.status(400).json({error:[...new Set(errors)].join('\n'),errors});if(db.prepare("SELECT id FROM monday_space_runs WHERE space_id=? AND status='running'").get(space.id))return res.status(409).json({error:'Space đang chạy. Chờ hoặc dừng lượt hiện tại.'});const runId=id(),state=Object.fromEntries(space.graph.nodes.map(n=>[n.id,require('../spaceSmart').validSnapshot(n.data.savedOutput)?{status:'completed',output:n.data.savedOutput}:{status:'waiting'}])),createdFiles=[];try{db.transaction(()=>{const frozen=snapshotGraph(space.graph,runId,createdFiles);db.prepare('INSERT INTO monday_space_runs VALUES(?,?,?,?,?,?,?)').run(runId,space.id,'running',JSON.stringify(frozen),JSON.stringify(state),now(),now())})();publishRefs();res.status(201).json({id:runId,status:'running'});tick()}catch(e){for(const file of createdFiles)try{fs.unlinkSync(file)}catch{}res.status(422).json({error:'Không khởi tạo được đầu vào workflow: '+e.message})}});

function inputsFor(run,node){const inputs={};for(const e of run.graph.edges.filter(e=>e.target===node.id&&e.data?.enabled!==false)){const h=e.targetHandle||'base',out=run.state[e.source]?.output;if(h==='prompt'&&inputs.prompt){const texts=[...(inputs.prompt.texts||[inputs.prompt.text]),...(out.texts||[out.text])];inputs.prompt={text:texts.join('\n\n'),texts,mediaType:'text'}}else if(h==='base'&&node.data.kind==='imageList'&&inputs.base)inputs.base={mediaType:'image',items:[...(inputs.base.items||[inputs.base]),...(out.items||[out])],refTags:[...(inputs.base.refTags||[]),...(out.refTags||[])]};else if(h==='guide'){const roleRefs=(out?.refTags||[]).map(tag=>({tag,role:e.data?.role||'unspecified'}));inputs.guide=inputs.guide?{...inputs.guide,refTags:[...inputs.guide.refTags,...(out?.refTags||[])],roleRefs:[...(inputs.guide.roleRefs||[]),...roleRefs]}:{...out,roleRefs}}else inputs[h]=out}return inputs}
const mediaActive=new Set();function startMedia(run,node){const key=run.id+':'+node.id+':'+(run.state[node.id].retry||0);if(mediaActive.has(key))return;mediaActive.add(key);Promise.resolve().then(()=>require(['motion','combine'].includes(node.data.kind)?'../spaceMedia':'../spaceComponents')[node.data.kind](key,inputsFor(run,node),node)).then(output=>finishLocalCutout(run.id,node.id,{status:'completed',output})).catch(e=>finishLocalCutout(run.id,node.id,{status:'failed',error:e.message})).finally(()=>mediaActive.delete(key))}
const fingerprintMemo=new WeakMap();function fingerprint(graph,id){let cache=fingerprintMemo.get(graph);if(!cache){cache=new Map();const byId=new Map(graph.nodes.map(n=>[n.id,n])),incoming=new Map(graph.nodes.map(n=>[n.id,[]])),outgoing=new Map(graph.nodes.map(n=>[n.id,[]])),degree=new Map(graph.nodes.map(n=>[n.id,0]));for(const e of graph.edges){if(e.data?.enabled===false)continue;incoming.get(e.target)?.push(e);outgoing.get(e.source)?.push(e);degree.set(e.target,(degree.get(e.target)||0)+1)}const queue=graph.nodes.filter(n=>!degree.get(n.id)).map(n=>n.id);for(let i=0;i<queue.length;i++){const nid=queue[i],node=byId.get(nid),data={...node.data};delete data.label;delete data.color;if(data.kind==='source'){const ref=db.prepare('SELECT filepath FROM ref_images WHERE tag=?').get(data.refTag||'');if(!ref||!fs.existsSync(ref.filepath)){cache.set(nid,'missing_'+data.refTag)}else data.refTag=crypto.createHash('sha256').update(fs.readFileSync(ref.filepath)).digest('hex')}if(!cache.has(nid))cache.set(nid,crypto.createHash('sha256').update(JSON.stringify({data,inputs:incoming.get(nid).map(e=>({handle:e.targetHandle||'base',role:e.data?.role,source:e.source,value:cache.get(e.source)}))})).digest('hex'));for(const e of outgoing.get(nid)){degree.set(e.target,degree.get(e.target)-1);if(!degree.get(e.target))queue.push(e.target)}}fingerprintMemo.set(graph,cache)}if(!cache.has(id))throw Error('Node không hợp lệ');return cache.get(id)}
router.post('/:id/nodes/:node/run',(req,res)=>{const space=parse(db.prepare('SELECT * FROM monday_spaces WHERE id=?').get(req.params.id));if(!space||space.archived_at)return res.status(404).json({error:'Space không tồn tại hoặc đang trong thùng rác'});const running=db.prepare("SELECT * FROM monday_space_runs WHERE space_id=? AND status='running'").all(space.id).map(parse);if(running.some(r=>['waiting','queued','processing','review'].includes(r.state[req.params.node]?.status)))return res.status(409).json({error:'Node này đang có tác vụ; các node khác vẫn có thể Run riêng.'});const target=space.graph.nodes.find(n=>n.id===req.params.node);if(!target)return res.status(404).json({error:'Không tìm thấy node'});if(['cutout','upscale'].includes(target.data.kind))return res.status(410).json({error:'Tính năng đã được gỡ'});const required=new Set([target.id]);const ancestors=[target.id],parents=new Map();for(const edge of space.graph.edges){if(edge.data?.enabled===false)continue;if(!parents.has(edge.target))parents.set(edge.target,[]);parents.get(edge.target).push(edge.source)}for(let i=0;i<ancestors.length;i++)for(const parent of (ancestors[i]!==target.id&&require('../spaceSmart').validSnapshot(space.graph.nodes.find(n=>n.id===ancestors[i])?.data.savedOutput)?[]:parents.get(ancestors[i])||[]))if(!required.has(parent)){required.add(parent);ancestors.push(parent)}const sub={...space.graph,nodes:space.graph.nodes.filter(n=>required.has(n.id)).map(({parentId,extent,...node})=>node),edges:space.graph.edges.filter(e=>e.data?.enabled!==false&&required.has(e.target)&&required.has(e.source))};const errors=validateGraph(sub,{ready:true,cachedIds:sub.nodes.filter(n=>n.id!==target.id&&require('../spaceSmart').validSnapshot(n.data.savedOutput)).map(n=>n.id)});if(target.data.kind==='aiPrompt'&&!require('../spaceComponents').aiConfigured())errors.push('Node viết prompt cần tài khoản MUSE trong Cài đặt');if(target.data.kind==='motion'&&!require('../spaceMedia').configured())errors.push('Motion Control chưa kết nối fal.ai. Mở node và nhập API key.');if(errors.length)return res.status(400).json({error:errors.join('\n')});const previous=db.prepare('SELECT * FROM monday_space_runs WHERE space_id=? ORDER BY created_at DESC LIMIT 30').all(space.id).map(parse),state={};for(const n of space.graph.nodes){const saved=require('../spaceSmart').validSnapshot(n.data.savedOutput)?{state:{[n.id]:{output:n.data.savedOutput}}}:null,cached=previous.find(r=>r.state[n.id]?.status==='completed'&&r.state[n.id]?.output&&(()=>{try{return fingerprint(r.graph.editorGraph||r.graph,n.id)===fingerprint(space.graph,n.id)}catch{return false}})())||saved;state[n.id]={status:'idle',...(cached?{output:cached.state[n.id].output}:{} )};if(!required.has(n.id))continue;if(n.id!==target.id&&saved){state[n.id]={status:'completed',output:saved.state[n.id].output};continue}if(n.id===target.id||['source','prompt','text','table','promptList','imageList','pickImage','videoSource','board','note'].includes(n.data.kind))state[n.id]={status:'waiting'};else if(cached)state[n.id]={status:'completed',output:cached.state[n.id].output};else return res.status(409).json({error:'Chạy và hoàn tất bước đầu vào trước: '+(n.data.label||n.data.kind)+'. Kết quả cũ có thể đã mất hiệu lực vì đầu vào thay đổi.'})}const runId=id(),createdFiles=[];try{db.transaction(()=>{const frozen=snapshotGraph({...space.graph,nodes:space.graph.nodes.filter(n=>required.has(n.id))},runId,createdFiles);frozen.nodes=space.graph.nodes.map(n=>frozen.nodes.find(f=>f.id===n.id)||n);frozen.editorGraph=space.graph;frozen.isolated=true;db.prepare('INSERT INTO monday_space_runs VALUES(?,?,?,?,?,?,?)').run(runId,space.id,'running',JSON.stringify(frozen),JSON.stringify(state),now(),now())})();res.status(201).json({id:runId,status:'running'});tick()}catch(e){for(const f of createdFiles)try{fs.unlinkSync(f)}catch{}res.status(422).json({error:e.message})}});

function publishRefs(){publishPublicRefs()}
function snapshotGraphSources(graph,runId,createdFiles){const frozen=structuredClone(graph),copies=new Map();frozen.editorGraph=structuredClone(graph);for(const n of frozen.nodes){if(n.data.kind==='videoSource'){require('../spaceMedia').asset(n.data.assetId);continue}if(n.data.kind!=='source'||require('../spaceSmart').validSnapshot(n.data.savedOutput))continue;const original=n.data.refTag;if(!copies.has(original)){const ref=db.prepare('SELECT * FROM ref_images WHERE tag=?').get(original);if(!ref||ref.archived_at||!fs.existsSync(ref.filepath))throw Error('Ảnh không còn trong thư viện: @'+original);const ext=path.extname(ref.filename).toLowerCase();if(!['.png','.jpg','.jpeg','.webp'].includes(ext))throw Error('Định dạng ảnh không được hỗ trợ');const refId=id(),filename='ref_'+refId+ext,target=path.join(DATA_DIR,'uploads',filename),tag='space_input_'+crypto.createHash('sha256').update(runId+':'+original).digest('hex').slice(0,16);fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(ref.filepath,target);createdFiles.push(target);db.prepare("INSERT INTO ref_images(id,tag,filename,filepath,size,mime_type,created_at) VALUES(?,?,?,?,?,?,datetime('now'))").run(refId,tag,filename,target,fs.statSync(target).size,ref.mime_type);db.prepare('UPDATE ref_images SET internal_only=1 WHERE tag=?').run(tag);copies.set(original,tag)}n.data.refTag=copies.get(original)}return frozen}
function snapshotGraph(graph,runId,createdFiles){const lists=new Map(graph.nodes.filter(n=>n.data.kind==='imageList').map(n=>[n.id,n]));const expanded={...graph,nodes:graph.nodes.flatMap(n=>n.data.kind==='imageList'?[n,...(n.data.refTags||[]).map((tag,i)=>({...n,id:n.id+'__list_'+i,data:{kind:'source',refTag:tag}}))]:[n])},frozen=snapshotGraphSources(expanded,runId,createdFiles);for(const [id,n]of lists){const item=frozen.nodes.find(x=>x.id===id);item.data.refTags=(n.data.refTags||[]).map((_,i)=>frozen.nodes.find(x=>x.id===id+'__list_'+i).data.refTag)}frozen.nodes=frozen.nodes.filter(n=>!Array.from(lists.keys()).some(id=>n.id.startsWith(id+'__list_')));return frozen}

function outputRef(job,run,node){const file=path.join(DATA_DIR,'videos',path.basename(job.video_url||''));if(!/^\/videos\/image_[\w.-]+\.(png|jpe?g|webp)$/i.test(job.video_url||''))throw Error('Đường dẫn kết quả ảnh không hợp lệ');if(!fs.existsSync(file))throw Error('File kết quả đã mất');const tag='space_'+crypto.createHash('sha256').update(run.id+':'+node.id+':'+job.id).digest('hex').slice(0,20);let ref=db.prepare('SELECT * FROM ref_images WHERE tag=?').get(tag);if(!ref){const refId=id(),filename='ref_'+refId+path.extname(file),target=path.join(DATA_DIR,'uploads',filename);fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(file,target);db.prepare("INSERT INTO ref_images(id,tag,filename,filepath,size,mime_type,created_at) VALUES(?,?,?,?,?,?,datetime('now'))").run(refId,tag,filename,target,fs.statSync(target).size,filename.endsWith('.webp')?'image/webp':filename.endsWith('.png')?'image/png':'image/jpeg');publishRefs()}return tag}
function startLocalCutout(run,node,base){const tag=base?.refTags?.[0];Promise.resolve().then(()=>{if(!tag)throw Error('Tách nền cần ảnh đầu vào');return require('../cutoutService').cutout({refTag:tag},{allowArchived:true})}).then(result=>finishLocalCutout(run.id,node.id,{status:'completed',jobId:result.job.id,output:{url:result.url,mediaType:'image',refTags:[result.reference.tag],anchorTags:base.anchorTags||base.refTags}})).catch(e=>finishLocalCutout(run.id,node.id,{status:'failed',error:e.message}))}
function finishLocalCutout(runId,nodeId,value){try{const current=parse(db.prepare('SELECT * FROM monday_space_runs WHERE id=?').get(runId));if(!current||current.status!=='running'||current.state[nodeId]?.status!=='processing')return;if(value.status==='completed'&&value.output?.mediaType==='video'&&current.graph.nodes.find(n=>n.id===nodeId)?.data.kind!=='download'){const jobId='space_video_'+crypto.createHash('sha256').update(runId+':'+nodeId).digest('hex').slice(0,20);db.prepare("INSERT OR IGNORE INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,video_url,created_at) VALUES(?,?,'[]','video','completed',100,?,?,0,0,15,?,datetime('now'))").run(jobId,current.graph.nodes.find(n=>n.id===nodeId)?.data.label||'Monday Space · video',Math.round(value.output.duration||10),current.graph.nodes.find(n=>n.id===nodeId)?.data.ratio||'16:9',value.output.url);value.jobId=jobId}if(value.status==='completed'&&value.output?.mediaType==='image'&&!value.output.refTags?.length){const job={id:'local_'+runId+nodeId,video_url:value.output.url};value.output.refTags=[outputRef(job,current,current.graph.nodes.find(n=>n.id===nodeId))]}current.state[nodeId]={...current.state[nodeId],...value};const states=Object.values(current.state),done=states.every(s=>['completed','failed','blocked','cancelled','idle'].includes(s.status)),status=done?(states.every(s=>['completed','idle'].includes(s.status))?'completed':'failed'):'running';db.prepare('UPDATE monday_space_runs SET status=?,state=?,updated_at=? WHERE id=?').run(status,JSON.stringify(current.state),now(),runId);broadcast('SPACE_RUN_UPDATED',{id:runId,status});if(value.status==='completed'&&value.jobId&&value.output?.mediaType==='video')broadcast('JOB_COMPLETED',{jobId:value.jobId,mediaType:'video',videoUrl:value.output.url});tick()}catch(e){console.error('[Space local]',e.message)}}
let ticking=false;
const generationActive=new Set();function startGeneration(run,node,inputs){const key=run.id+':'+node.id;if(generationActive.has(key))return;generationActive.add(key);Promise.resolve().then(async()=>{if(node.data.multiEdit)node={...node,data:{...node.data,ratio:await require('../spaceSmart').resolveEditRatio(node.data,inputs)}};inputs=await require('../spaceSmart').packGuides(key,inputs,{productStudio:node.data.productStudio===true});const current=parse(db.prepare('SELECT * FROM monday_space_runs WHERE id=?').get(run.id));if(current?.status!=='running'||current.state[node.id]?.status!=='processing')return;const spec=compileNode(node,inputs),guard=require('../generationGuard').inspectGeneration({...spec,prompts:[spec.prompt]},{allowArchived:true});if(!guard.valid)throw Error(guard.errors.join('; '));if(spec.refTags.length>4)throw Error('MUSE nhận tối đa 4 file trong một yêu cầu. Đưa ảnh bổ sung vào Guide.');const jobId='task_'+crypto.createHash('sha256').update(run.id+':'+node.id+':'+(current.state[node.id].retry||0)).digest('hex').slice(0,16);db.prepare("INSERT OR IGNORE INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,batch_id,sort_order,created_at) VALUES(?,?,?,?,'pending',0,?,?,0,0,15,?,0,datetime('now'))").run(jobId,spec.prompt,JSON.stringify(spec.refTags),spec.mediaType,spec.duration,spec.ratio,'space_'+run.id);current.state[node.id]={...current.state[node.id],jobId,status:'queued',ratio:spec.ratio};db.prepare('UPDATE monday_space_runs SET state=?,updated_at=? WHERE id=?').run(JSON.stringify(current.state),now(),run.id);if(!dispatcher.isRunning())dispatcher.start(broadcast);else dispatcher.trigger()}).catch(e=>finishLocalCutout(run.id,node.id,{status:'failed',error:e.message})).finally(()=>generationActive.delete(key))}
function tick(){if(ticking)return;ticking=true;try{const runs=db.prepare("SELECT * FROM monday_space_runs WHERE status='running'").all().map(parse);for(const run of runs){let changed=false;for(const node of run.graph.nodes){const s=run.state[node.id];if(s.status==='processing'&&['image','clone','outfit','angle','pose','style','material','colorMatch','video','storyboard'].includes(node.data.kind)){startGeneration(run,node,inputsFor(run,node));continue}if(s.status==='processing'&&['motion','combine','aiPrompt','upscale','download','splitStoryboard','pickImage'].includes(node.data.kind)){startMedia(run,node);continue}if(['completed','failed','blocked','cancelled','idle','processing','review'].includes(s.status))continue;if(s.jobId){const job=db.prepare('SELECT * FROM jobs WHERE id=?').get(s.jobId);if(!job||['failed','stopped'].includes(job.status)){s.status='failed';s.error=job?.error||'Tác vụ đã dừng hoặc không còn';changed=true}else if(job.status==='completed'){try{const newTags=job.media_type==='image'?[outputRef(job,run,node)]:[];const baseEdge=run.graph.edges.find(e=>e.target===node.id&&e.data?.enabled!==false&&(e.targetHandle||'base')==='base'),base=baseEdge?run.state[baseEdge.source]?.output:null;s.output={url:job.video_url,mediaType:job.media_type,ratio:job.ratio,...(node.data.kind==='storyboard'?{columns:node.data.columns??3,rowsCount:node.data.rowsCount??2}:{}),refTags:newTags,anchorTags:base?.anchorTags||base?.refTags||newTags};s.status=!run.graph.isolated&&job.media_type==='image'&&run.graph.reviewBeforeNext!==false&&run.graph.edges.some(e=>e.data?.enabled!==false&&e.source===node.id&&run.graph.nodes.find(n=>n.id===e.target)?.data.kind!=='output')?'review':'completed'}catch(e){if(busyError(e))continue;s.status='failed';s.error=e.message}changed=true}continue}
const incoming=run.graph.edges.filter(e=>e.target===node.id&&e.data?.enabled!==false),parents=incoming.map(e=>run.state[e.source]);if(parents.some(s=>['failed','blocked','cancelled'].includes(s.status))){s.status='blocked';s.error='Bước trước chưa thành công';changed=true;continue}if(parents.some(s=>s.status!=='completed'))continue;
try{if(['board','note'].includes(node.data.kind)){s.status='completed'}else if(node.data.kind==='videoSource'){s.output=require('../spaceMedia').asset(node.data.assetId);s.status='completed'}else if(node.data.kind==='source'){const ref=db.prepare('SELECT * FROM ref_images WHERE tag=?').get(node.data.refTag);if(!ref||!fs.existsSync(ref.filepath))throw Error('Ảnh nguồn đã mất');s.output={url:'/uploads/'+ref.filename,refTags:[ref.tag],anchorTags:[ref.tag],mediaType:'image'};s.status='completed'}else if(node.data.kind==='imageList'){s.output=require('../spaceSmart').imageList(node,inputsFor(run,node));s.status='completed'}else if(['prompt','text','table','promptList'].includes(node.data.kind)){s.output=require('../spaceComponents').textOutput(node,inputsFor(run,node));s.status='completed'}else{const inputs=inputsFor(run,node);if(node.data.kind==='joinText'){s.output=require('../spaceComponents').textOutput(node,inputs);s.status='completed'}else if(node.data.kind==='delay'){s.wakeAt??=Date.now()+Number(node.data.seconds??5)*1000;if(Date.now()>=s.wakeAt){s.output=inputs.base;s.status='completed'}}else if(node.data.kind==='output'){s.output=inputs.base;s.status='completed'}else if(['combine','motion','aiPrompt','upscale','download','splitStoryboard','pickImage'].includes(node.data.kind)){s.status='processing';startMedia(run,node)}else if(node.data.kind==='cutout'){s.status='processing';startLocalCutout(run,node,inputs.base)}else{s.status='processing';startGeneration(run,node,inputs)}}changed=true}catch(e){if(busyError(e))continue;s.status='failed';s.error=e.message;changed=true}}
if(changed){const states=Object.values(run.state),done=states.every(s=>['completed','failed','blocked','cancelled','idle'].includes(s.status)),status=done?(states.every(s=>['completed','idle'].includes(s.status))?'completed':'failed'):'running';db.prepare('UPDATE monday_space_runs SET status=?,state=?,updated_at=? WHERE id=?').run(status,JSON.stringify(run.state),now(),run.id);broadcast('SPACE_RUN_UPDATED',{id:run.id,status})}}
}catch(e){console.error('[Monday Space]',e.message)}finally{ticking=false}}
const timer=setInterval(tick,2000);timer.unref();router.tick=tick;module.exports=router;
